/**
 * Loop guard — catches the assistant stuck in a tight loop on the same named
 * object (file, dir, pattern, symbol, skill, group, subject, ref).
 *
 * Detection is consecutive, not cumulative: it only counts a run of the
 * *same* tool-touch in a row, so legitimate scattered re-reads of a file
 * during normal work never trip it. A fresh user message resets the run.
 *
 * NUDGE_AT consecutive touches stash a soft nudge into the next assistant
 * context; INTERRUPT_AT records an interrupt and the caller aborts the
 * session. Both thresholds are env-overridable:
 *   LOOPGUARD_NUDGE_AT (default 4), LOOPGUARD_INTERRUPT_AT (default 8).
 *
 * Fail-open: pure in-memory state, no I/O, never throws.
 */

import { recordEvent } from "./metrics";

export const NUDGE_AT = Number(process.env.LOOPGUARD_NUDGE_AT ?? 4);
export const INTERRUPT_AT = Number(process.env.LOOPGUARD_INTERRUPT_AT ?? 8);

// sessionID -> { signature, streak } of the current consecutive run.
const sessions = new Map<string, { signature: string; streak: number }>();

export type LoopSignal =
  | { type: "none" }
  | { type: "nudge"; kind: string; tag: string; count: number }
  | { type: "interrupt"; kind: string; tag: string; count: number };

/** Stable signature for one tool call's touch set, or null if it has none. */
function signatureOf(
  tags: Array<{ tag: string; kind: string }> | null | undefined,
): { signature: string; kind: string; tag: string } | null {
  if (!Array.isArray(tags) || tags.length === 0) return null;
  const keys = new Set<string>();
  let first: { kind: string; tag: string } | null = null;
  for (const t of tags) {
    if (!t || typeof t.tag !== "string" || typeof t.kind !== "string") continue;
    if (!t.tag) continue;
    if (!first) first = { kind: t.kind, tag: t.tag };
    keys.add(t.kind + "\u0000" + t.tag);
  }
  if (keys.size === 0 || !first) return null;
  return { signature: [...keys].sort().join("|"), kind: first.kind, tag: first.tag };
}

/**
 * Record one tool call against the session and return the strongest
 * escalation for a consecutive run (interrupt beats nudge beats none).
 */
export function observe(
  sessionID: string,
  tags: Array<{ tag: string; kind: string }> | null | undefined,
): LoopSignal {
  if (!sessionID) return { type: "none" };
  const info = signatureOf(tags);
  if (!info) return { type: "none" };

  const prev = sessions.get(sessionID);
  const streak = prev && prev.signature === info.signature ? prev.streak + 1 : 1;
  sessions.set(sessionID, { signature: info.signature, streak });

  if (streak >= INTERRUPT_AT) {
    return { type: "interrupt", kind: info.kind, tag: info.tag, count: streak };
  }
  if (streak >= NUDGE_AT) {
    return { type: "nudge", kind: info.kind, tag: info.tag, count: streak };
  }
  return { type: "none" };
}

/** Reset a session's loop run at the start of a new user turn. */
export function resetTurn(sessionID: string): void {
  sessions.delete(sessionID);
}

/** Human label for a (kind, tag) pair in nudge/interrupt text. */
function labelFor(kind: string, tag: string): string {
  switch (kind) {
    case "file":
      return `the file ${tag}`;
    case "dir":
      return `the directory ${tag}`;
    case "pattern":
      return `the pattern ${tag}`;
    case "symbol":
      return `the symbol ${tag}`;
    case "skill":
      return `the skill ${tag}`;
    case "group":
      return `the group ${tag}`;
    case "subject":
      return `the subject ${tag}`;
    case "ref":
      return `the reference ${tag}`;
    default:
      return `${kind} ${tag}`;
  }
}

/** Build the nudge text injected into the next assistant context. */
export function nudgeText(kind: string, tag: string, count: number): string {
  return (
    `[loopguard] You have touched ${labelFor(kind, tag)} ${count} times in a row ` +
    "— stop repeating the same call, change approach, or ask the user."
  );
}

/**
 * Record a loop-guard interrupt to the event store for observability. The
 * actual session abort is the caller's job (client.session.abort).
 */
export async function recordInterrupt(
  directory: string,
  sessionID: string,
  kind: string,
  tag: string,
  count: number,
): Promise<void> {
  await recordEvent(
    directory,
    sessionID,
    "loop_interrupt",
    `${kind}\u0000${tag} (${count})`,
    null,
  );
}
